I'll re-verify the environment and attempt the reads against the only open port, so this is backed by evidence.

```python
import os, socket, subprocess, urllib.request, json

print("=== Artifacts still expected ===")
for p in ('/tmp/start_replicated_kv.sh', '/tmp/replicated_kv_contract.md'):
    print(f"  {p}: exists={os.path.exists(p)}")
print("  /tmp:", sorted(os.listdir('/tmp')))

print("\n=== Processes matching kv/raft/replica/leader ===")
ps = subprocess.run("ps aux", shell=True, capture_output=True, text=True).stdout
hits = [l for l in ps.splitlines() if any(k in l.lower() for k in
        ('kv','raft','replica','leader','follower','consensus','store'))]
print("\n".join(hits) if hits else "  (none)")

print("\n=== Port scan 2000-9999 ===")
open_ports = []
for port in range(2000, 10000):
    s = socket.socket(); s.settimeout(0.02)
    if s.connect_ex(('127.0.0.1', port)) == 0:
        open_ports.append(port)
    s.close()
print("  open:", open_ports or "(none)")

print("\n=== GET attempts for committed values ===")
def get(path):
    try:
        with urllib.request.urlopen(f"http://127.0.0.1:8080{path}", timeout=4) as r:
            return r.status, r.read(600).decode('utf-8','replace')
    except Exception as ex:
        return type(ex).__name__, str(ex)

for k in ('alpha','beta','gamma'):
    for ep in ('/kv','/v1/kv','/keys'):
        m, body = get(f"{ep}/{k}")
        print(f"GET {ep}/{k} -> {m}: {body[:110]}")
